"use client";

import { TableRow, TableCell, Skeleton } from "@mui/material";
import { cellSx } from "@/lib/theme-shared";

type TableSkeletonRowsProps = {
  rows?: number;
  columns: number[];
};

/**
 * Renders skeleton loading rows for data tables.
 * @param rows - Number of skeleton rows to render (default: 5)
 * @param columns - Array of widths for each column's skeleton
 */
export default function TableSkeletonRows({
  rows = 5,
  columns,
}: TableSkeletonRowsProps) {
  return (
    <>
      {Array.from({ length: rows }, (_, idx) => (
        <TableRow key={idx}>
          {columns.map((width, colIdx) => (
            <TableCell key={colIdx} sx={colIdx === columns.length - 1 ? { ...cellSx, textAlign: "center" } : cellSx}>
              {colIdx === columns.length - 1 ? (
                <Skeleton
                  variant="rectangular"
                  height={20}
                  width={width}
                  sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "4px", mx: "auto" }}
                />
              ) : (
                <Skeleton
                  variant="text"
                  width={width}
                  sx={{ bgcolor: "rgba(255,255,255,0.06)" }}
                />
              )}
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}
