/**
 * Currency & Number Formatting Utilities
 */

const currencyFormats: Record<string, { locale: string; symbol: string }> = {
  IDR: { locale: 'id-ID', symbol: 'Rp' },
  USD: { locale: 'en-US', symbol: '$' },
  USDT: { locale: 'en-US', symbol: 'USDT' },
  BTC: { locale: 'en-US', symbol: '₿' },
  ETH: { locale: 'en-US', symbol: 'Ξ' },
}

/**
 * Format number as currency
 */
export function formatCurrency(
  amount: number,
  currency: string = 'IDR',
  options?: { minimumFractionDigits?: number; maximumFractionDigits?: number }
): string {
  const config = currencyFormats[currency] || { locale: 'en-US', symbol: currency }
  
  const formatter = new Intl.NumberFormat(config.locale, {
    style: 'currency',
    currency,
    minimumFractionDigits: options?.minimumFractionDigits ?? 0,
    maximumFractionDigits: options?.maximumFractionDigits ?? 2,
  })

  return formatter.format(amount)
}

/**
 * Format number as percentage
 */
export function formatPercent(value: number, decimals: number = 2): string {
  return (value * 100).toFixed(decimals) + '%'
}

/**
 * Format large numbers dengan K, M, B suffix
 */
export function formatCompact(value: number): string {
  return new Intl.NumberFormat("id-ID", { maximumFractionDigits: 0 }).format(Math.round(value));
}

/**
 * Parse currency string ke number
 */
export function parseCurrency(input: string): number {
  const cleaned = input.replace(/[^\d.-]/g, '')
  return parseFloat(cleaned) || 0
}

/**
 * Format dengan custom suffix
 */
export function formatWithSuffix(value: number, suffix: string, decimals: number = 2): string {
  return value.toFixed(decimals) + ' ' + suffix
}

/**
 * Validate if value adalah valid currency amount
 */
export function isValidCurrencyAmount(value: any, minAmount: number = 0): boolean {
  if (typeof value === 'number') {
    return value > minAmount && isFinite(value)
  }
  if (typeof value === 'string') {
    const num = parseFloat(value)
    return num > minAmount && isFinite(num)
  }
  return false
}

/**
 * Format currency automatically (0 decimals for IDR, 2 decimals for USD and other currencies)
 */
export function formatCurrencyAuto(n: number, currency: string = "USD"): string {
  return formatCurrency(n, currency, {
    minimumFractionDigits: currency === "IDR" ? 0 : 2,
    maximumFractionDigits: currency === "IDR" ? 0 : 2,
  });
}

/**
 * Format number as USD with 2 decimal digits
 */
export function formatUSD(n: number): string {
  return formatCurrency(n, "USD", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/**
 * Format numeric quantity with locale formatting for readability
 */
export function formatQuantity(n: number): string {
  return n >= 1000 ? n.toLocaleString("en-US") : n.toString();
}

/**
 * Convert currency using rate configurations
 */
export function convertCurrency(
  amount: number,
  fromCurrency: string,
  toCurrency: string,
  rates: { code: string; rate: number }[]
): number {
  if (fromCurrency === toCurrency) return amount;
  const fromRateObj = rates.find(r => r.code === fromCurrency);
  const toRateObj = rates.find(r => r.code === toCurrency);
  
  const fromRate = fromCurrency === 'USD' ? 1 : (fromRateObj?.rate ?? null);
  const toRate = toCurrency === 'USD' ? 1 : (toRateObj?.rate ?? null);

  if (fromRate === null || toRate === null) {
    return 0;
  }
  
  return (amount / fromRate) * toRate;
}

/**
 * Extract currency symbol/code for a matching object ID from a list
 */
export function getExCurrency(exId: string, exchanges: { id: string; currency: string }[]): string {
  return exchanges.find(e => e.id === exId)?.currency || 'USD';
}
